using System.Drawing;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyControl : UserControl
{
    public string DisplayName { get; set; }
    public int MaxItems { get; set; }

    public MyControl()
    {
        // .NET 9 breaking change: StatusStrip no longer defaults to the system
        // professional renderer. Explicitly set it to preserve .NET 8 appearance.
        var statusStrip = new StatusStrip();
        statusStrip.RenderMode = ToolStripRenderMode.System;
        Controls.Add(statusStrip);
    }

    /// <summary>
    /// Shows a drop-down editor. In .NET 9, passing null to DropDownControl
    /// throws ArgumentNullException, so a guard is required.
    /// </summary>
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control control)
    {
        if (control is not null)
        {
            editorService.DropDownControl(control);
        }
    }
}

